import { test, expect } from '@playwright/test';

test('Playground header, honest composer labels and scrollable suggestions at each size',async({page})=>{
  await page.goto('/entry');
  await page.getByLabel('Ask anything').fill('I am building a travel agent. How can I improve my agent success rate with neatlogs?');
  await page.getByRole('button',{name:'Send message'}).click();
  await expect(page).toHaveURL(/\/demo\/[^/]+\/traces$/);
  const panel=page.getByRole('complementary',{name:'Playground'});
  await expect(panel.locator('[data-status]').last()).toBeVisible();
  for(const [width,height] of [[980,729],[1440,900],[390,844]]){
    await page.setViewportSize({width,height});
    await expect(panel.locator('header strong')).toHaveText('Playground');
    await expect(panel.locator('.playground-attribution')).toHaveText('Powered by Tailor');
    await expect(panel.locator('.tailor-pill')).toHaveText('Tailor');
    await expect(panel.locator('[data-exec-line]')).toHaveCount(0);
    await expect(panel.locator('.chat-tools .chat-chip').first()).toBeVisible();
    await expect(panel.locator('[data-exec-chip]')).toHaveText('Mock-backed');
    const list=panel.locator('.chat-examples');
    await expect(list).toBeVisible();
    await expect(list.locator('button')).toHaveCount(3);
    const metrics=await list.evaluate(el=>({width:el.clientWidth,scroll:el.scrollWidth,overflow:getComputedStyle(el).overflowX,wrap:getComputedStyle(el).flexWrap,ys:Array.from(el.children).map(c=>c.getBoundingClientRect().y)}));
    expect(metrics.overflow).toBe('auto');expect(metrics.wrap).toBe('nowrap');
    expect(metrics.scroll).toBeGreaterThan(metrics.width);
    expect(new Set(metrics.ys).size).toBe(1);
    await list.locator('button').last().focus();
    const scroll=await list.evaluate(el=>el.scrollLeft);expect(scroll).toBeGreaterThan(0);
    const last=list.locator('button').last(),prompt=await last.getAttribute('data-example');
    await last.click();await expect(panel.getByLabel('Ask anything')).toHaveValue(prompt!);
    await expect(panel.getByLabel('Ask anything')).toBeFocused();
    const composer=await panel.locator('.chat-composer').boundingBox(),thread=await panel.locator('.chat-thread').boundingBox();
    expect(thread!.height).toBeGreaterThan(0);expect(composer!.y+composer!.height).toBeLessThanOrEqual(height);
    await panel.getByLabel('Ask anything').fill('');
    await page.screenshot({path:`.local/review-evidence/panel-after-${width}.png`,fullPage:true});
  }
  await page.setViewportSize({width:980,height:729});
  await page.getByRole('button',{name:'Collapse conversation'}).click();
  await expect(panel).toHaveCount(0);
  await page.getByRole('button',{name:'Open conversation'}).click();
  await expect(panel.locator('header strong')).toHaveText('Playground');
});
.chat-stage{min-height:calc(100vh - 74px);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:24px 16px 48px;text-align:center}
.chat-stage h1{margin:0;font-size:36px;font-weight:500;letter-spacing:-.03em}
.chat-stage>p{margin:0;font-size:16px;color:#4b4b52}
.chat-examples{display:flex;flex-wrap:wrap;justify-content:center;gap:8px 14px}
.chat-examples button{border:0;background:transparent;color:#2766c7;padding:2px 0;font-size:13px}
.chat-composer{width:min(720px,100%);background:#fff;border:1px solid #d9d9de;border-radius:28px;padding:16px;box-shadow:0 8px 24px rgb(0 0 0 / .06);text-align:left}
.chat-label{margin:0;font-size:12px;color:var(--muted)}
.chat-composer textarea{display:block;width:100%;border:0;resize:none;background:transparent;min-height:32px;font-size:13px;line-height:20px}
.chat-tools{display:flex;align-items:center;gap:8px;margin-top:12px}
.chat-chip{border:1px solid var(--line);border-radius:999px;padding:4px 10px;font-size:12px;white-space:nowrap}
.chat-tools button{margin-left:auto;width:28px;height:28px;border:0;border-radius:999px;padding:0;background:#18181b;color:#fff}
.chat-thread{width:min(720px,100%);text-align:left;display:flex;flex-direction:column;gap:10px}
.chat-turn p{display:inline-block;max-width:92%;margin:0;padding:8px 12px;border:1px solid var(--line);border-radius:12px;background:#fff;line-height:1.45}
.chat-turn.is-buyer{text-align:right}.chat-turn small{display:block;margin-top:4px;color:var(--muted);font-size:10px}
.chat-panel{position:fixed;top:0;right:0;bottom:0;z-index:4;width:var(--chat-w);display:flex;flex-direction:column;gap:8px;padding:12px;background:var(--ground);border-left:1px solid var(--line);overflow:hidden}
.chat-panel header{display:flex;align-items:center;justify-content:space-between}.chat-panel header button{border:0;background:transparent}
.chat-panel .chat-thread{width:100%;flex:1;overflow:auto}.chat-panel .chat-composer{width:100%;box-shadow:none}
.chat-reopen{margin:8px 16px;align-self:flex-start}
